      "HLOOKUP": {
        "description": "Ищет значение в первой строке таблицы или массива и возвращает значение, находящееся в том же столбце в заданной строке таблицы или массива. Функция ГПР используется, когда сравниваемые значения расположены в первой строке таблицы данных, а возвращаемые — на несколько строк ниже. Если сравниваемые значения находятся в столбце слева от искомых данных, используйте функцию ВПР.",
        "abstract": "Ищет значение в первой строке таблицы или массива и возвращает значение, находящееся в том же столбце в заданной строке таблицы или массива. Функция ГПР используется, когда сравниваемые значения расположены в первой строке таблицы данных, а возвращаемые — на несколько строк ниже. Если сравниваемые значения находятся в столбце слева от искомых данных, используйте функцию ВПР.",
        "links": [
          {
            "title": "Инструкция",
            "url": "https://support.microsoft.com/ru-ru/excel/functions/hlookup-function"
          }
        ],
        "functionParameter": {
          "lookupValue": {
            "name": "искомое значение",
            "detail": "Обязательно. Значение, которое требуется найти в первой строке таблицы. \"Искомое_значение\" может быть значением, ссылкой или текстовой строкой."
          },
          "tableArray": {
            "name": "таблица",
            "detail": "Обязательно. Таблица, в которой производится поиск данных. Можно использовать ссылку на диапазон или имя диапазона. Значения в первой строке аргумента \"таблица\" могут быть текстом, числами или логическими значениями. Если аргумент \"интервальный_просмотр\" имеет значение ИСТИНА, то значения в первой строке аргумента \"таблица\" должны быть расположены в возрастающем порядке: ...-2, -1, 0, 1, 2, ..., A-Z, ЛОЖЬ, ИСТИНА; в противном случае функция ГПР может выдать неправильный результат. Если аргумент \"интервальный_просмотр\" имеет значение ЛОЖЬ, таблица может быть не отсортирована. В текстовых строках регистр букв не учитывается. Значения сортируются слева направо по возрастанию. Дополнительные сведения см. в разделе Сортировка данных в диапазоне или таблице ."
          },
          "rowIndexNum": {
            "name": "номер строки",
            "detail": "Обязательно. Номер строки в аргументе \"таблица\", из которой будет возвращено соответствующее значение. Если значение аргумента \"номер_строки\" равно 1, возвращается значение из первой строки аргумента \"таблица\", если оно равно 2 — из второй строки и т. д. Если значение аргумента \"номер_строки\" меньше 1, функция ГПР возвращает значение ошибки #ЗНАЧ!; если оно больше, чем количество строк в аргументе \"таблица\", возвращается значение ошибки #ССЫЛ!."
          },
          "rangeLookup": {
            "name": "интервальный просмотр",
            "detail": "Дополнительные. Логическое значение, которое определяет, какое соответствие должна искать функция ГПР — точное или приблизительное. Если этот аргумент имеет значение ИСТИНА или опущен, возвращается приблизительное соответствие; при отсутствии точного соответствия возвращается наибольшее из значений, меньших, чем \"искомое_значение\". Если этот аргумент имеет значение ЛОЖЬ, функция ГПР ищет точное соответствие. Если найти его не удается, возвращается значение ошибки #Н/Д."
          }
        }
      },
